//! Owner-thread table for native COM identities used by Win16 adapters.
//!
//! COM identity, QueryInterface, and reference counting use `windows-core`'s
//! generated IUnknown interface wrapper. Other classic COM interfaces are
//! generated by the second, narrowly filtered `windows-bindgen` module; no
//! interface vtable layout is restated in this object table.

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::ffi::c_void;
use std::fmt;
use std::ptr;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

use compat_services::com::{ComObjectId, Guid};
use runtime::{Win16ComHostOwnedMediumId, Win16ComHostOwnerIdentity};
use windows_core::{GUID as NativeGuid, HRESULT, IUnknown, Interface};
use windows_sys::Win32::System::Com::{APTTYPE, APTTYPE_MAINSTA, APTTYPE_STA, CoGetApartmentType};

use super::com_bindings::generated::{ReleaseStgMedium, STGMEDIUM};

// Host object keys and medium tokens are process-wide monotonic identities.
// A replacement STA therefore cannot accidentally reuse a stale token from
// the previous owner generation.
static NEXT_NATIVE_COM_OBJECT_ID: AtomicU64 = AtomicU64::new(1);
static NEXT_NATIVE_COM_MEDIUM_ID: AtomicU64 = AtomicU64::new(1);

struct NativeComEntry {
    /// One stable canonical identity for lookups and temporary QI operations.
    /// It owns an additional native reference independently of the guest refs.
    canonical: Arc<IUnknown>,
    /// One windows-core owned IUnknown for each bridge-owned reference.
    references: Vec<IUnknown>,
}

struct NativeComInterfaceLease(IUnknown);

impl NativeComInterfaceLease {
    pub(super) fn as_raw(&self) -> *mut c_void {
        self.0.as_raw()
    }
}

/// Typed failures from the native COM object table.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum NativeComError {
    NullInterface,
    UnknownObject(ComObjectId),
    UnknownMedium(Win16ComHostOwnedMediumId),
    WrongThread {
        owner: u32,
        current: u32,
    },
    InvalidOwnerIdentity,
    IdentitySpaceExhausted,
    ApartmentQuery(HRESULT),
    WrongApartment(APTTYPE),
    ReferenceCountOverflow,
    InvalidQueryResult,
    HResult {
        operation: &'static str,
        result: HRESULT,
    },
}

impl fmt::Display for NativeComError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NullInterface => formatter.write_str("native COM interface pointer is null"),
            Self::UnknownObject(object) => write!(
                formatter,
                "native COM object {} is not registered",
                object.0
            ),
            Self::UnknownMedium(medium) => write!(
                formatter,
                "native COM storage medium {}:{} is not registered",
                medium.owner.id, medium.id,
            ),
            Self::WrongThread { owner, current } => write!(
                formatter,
                "native COM object belongs to thread {owner}, current thread is {current}",
            ),
            Self::InvalidOwnerIdentity => {
                formatter.write_str("native COM owner identity is invalid")
            }
            Self::IdentitySpaceExhausted => {
                formatter.write_str("native COM identity space was exhausted")
            }
            Self::ApartmentQuery(result) => write!(
                formatter,
                "native COM apartment query failed with HRESULT 0x{:08X}",
                result.0 as u32,
            ),
            Self::WrongApartment(apartment) => write!(
                formatter,
                "native COM owner must be an STA (reported apartment type {apartment})",
            ),
            Self::ReferenceCountOverflow => {
                formatter.write_str("native COM reference count overflowed")
            }
            Self::InvalidQueryResult => {
                formatter.write_str("native QueryInterface returned a null interface on success")
            }
            Self::HResult { operation, result } => {
                write!(
                    formatter,
                    "native COM {operation} failed with HRESULT 0x{:08X}",
                    result.0 as u32
                )
            }
        }
    }
}

impl std::error::Error for NativeComError {}

struct Win16ComObjectState {
    by_id: BTreeMap<ComObjectId, NativeComEntry>,
    by_unknown: BTreeMap<usize, ComObjectId>,
    media: BTreeMap<Win16ComHostOwnedMediumId, STGMEDIUM>,
}

impl Win16ComObjectState {
    fn empty() -> Self {
        Self {
            by_id: BTreeMap::new(),
            by_unknown: BTreeMap::new(),
            media: BTreeMap::new(),
        }
    }
}

/// A host-only table of canonical native IUnknown identities. `RefCell` is
/// never borrowed across an interface call or QueryInterface; the native
/// references use windows-core's official IUnknown implementation.
pub(super) struct Win16ComObjects {
    owner_thread: u32,
    owner_identity: Win16ComHostOwnerIdentity,
    state: RefCell<Win16ComObjectState>,
}

impl Win16ComObjects {
    /// Bind the object table to the already initialized USER STA. COM/OLE
    /// pointers are apartment-affine; a thread ID alone is not proof that this
    /// is the required apartment.
    pub(super) fn new(owner_identity: Win16ComHostOwnerIdentity) -> Result<Self, NativeComError> {
        if !owner_identity.is_valid() {
            return Err(NativeComError::InvalidOwnerIdentity);
        }
        // SAFETY: GetCurrentThreadId has no pointer or initialization preconditions.
        let owner_thread = { crate::windows::win32_safe::current_thread_id() };
        let mut apartment: APTTYPE = 0;
        let mut qualifier = 0;
        // SAFETY: both output slots are valid and COM has been initialized by
        // the USER worker before it constructs this table.
        let result = unsafe { CoGetApartmentType(&mut apartment, &mut qualifier) };
        if result < 0 {
            return Err(NativeComError::ApartmentQuery(HRESULT(result)));
        }
        if !matches!(apartment, APTTYPE_STA | APTTYPE_MAINSTA) {
            return Err(NativeComError::WrongApartment(apartment));
        }
        Ok(Self {
            owner_thread,
            owner_identity,
            state: RefCell::new(Win16ComObjectState::empty()),
        })
    }

    pub(super) fn owner_identity(&self) -> Win16ComHostOwnerIdentity {
        self.owner_identity
    }

    /// Consume one owned native interface reference and return its stable,
    /// opaque object key. QI for canonical IUnknown uses windows-core; repeated
    /// identities are folded into the existing bridge entry.
    pub(super) fn insert_owned(
        &self,
        interface: *mut c_void,
    ) -> Result<ComObjectId, NativeComError> {
        self.check_thread()?;
        if interface.is_null() {
            return Err(NativeComError::NullInterface);
        }
        // SAFETY: caller transfers one owned COM interface reference. IUnknown
        // has the standard COM ABI and windows-core owns/releases it.
        let owned = unsafe { IUnknown::from_raw(interface) };
        let canonical = owned
            .cast::<IUnknown>()
            .map_err(|error| NativeComError::HResult {
                operation: "QueryInterface(IUnknown)",
                result: HRESULT(error.code().0),
            })?;
        drop(owned);
        let address = canonical.as_raw() as usize;

        // Hold an independent canonical reference so lookups can pin identity
        // without invoking AddRef while the RefCell table is borrowed.
        let canonical_pin = Arc::new(canonical.clone());
        let mut state = self.state.borrow_mut();
        if let Some(object) = state.by_unknown.get(&address).copied() {
            let can_add = state
                .by_id
                .get(&object)
                .ok_or(NativeComError::UnknownObject(object))?
                .references
                .len();
            if u32::try_from(can_add)
                .ok()
                .and_then(|count| count.checked_add(1))
                .is_none()
            {
                drop(state);
                drop(canonical_pin);
                return Err(NativeComError::ReferenceCountOverflow);
            }
            state
                .by_id
                .get_mut(&object)
                .ok_or(NativeComError::UnknownObject(object))?
                .references
                .push(canonical);
            drop(state);
            drop(canonical_pin);
            return Ok(object);
        }

        let object = match allocate_identity(&NEXT_NATIVE_COM_OBJECT_ID) {
            Ok(id) => ComObjectId(id),
            Err(error) => {
                drop(state);
                drop(canonical);
                drop(canonical_pin);
                return Err(error);
            }
        };
        state.by_unknown.insert(address, object);
        state.by_id.insert(
            object,
            NativeComEntry {
                canonical: canonical_pin,
                references: vec![canonical],
            },
        );
        Ok(object)
    }

    /// Consume an owned native interface reference returned on a failing
    /// HRESULT. It is not inserted into the guest object table.
    pub(super) fn discard_owned(&self, interface: *mut c_void) -> Result<(), NativeComError> {
        self.check_thread()?;
        if !interface.is_null() {
            // SAFETY: caller transfers the failing API's output reference.
            drop(unsafe { IUnknown::from_raw(interface) });
        }
        Ok(())
    }

    /// Release one bridge-owned native reference. Remove the entry before
    /// dropping its final COM wrappers so Release cannot reenter a borrowed
    /// table entry.
    pub(super) fn release(&self, object: ComObjectId) -> Result<u32, NativeComError> {
        self.check_thread()?;
        let (released, retired, remaining) = {
            let mut state = self.state.borrow_mut();
            let entry = state
                .by_id
                .get_mut(&object)
                .ok_or(NativeComError::UnknownObject(object))?;
            let remaining = entry
                .references
                .len()
                .checked_sub(1)
                .and_then(|count| u32::try_from(count).ok())
                .ok_or(NativeComError::ReferenceCountOverflow)?;
            let Some(released) = entry.references.pop() else {
                return Err(NativeComError::UnknownObject(object));
            };
            if remaining == 0 {
                let address = entry.canonical.as_raw() as usize;
                state.by_unknown.remove(&address);
                let retired = state.by_id.remove(&object);
                (released, retired, remaining)
            } else {
                (released, None, remaining)
            }
        };
        drop(released);
        drop(retired);
        Ok(remaining)
    }

    /// Temporarily query for one interface and execute a host-private call.
    /// The object table is unborrowed before QI or the interface method runs.
    pub(super) fn with_interface<R>(
        &self,
        object: ComObjectId,
        iid: Guid,
        operation: impl FnOnce(*mut c_void) -> R,
    ) -> Result<Option<R>, NativeComError> {
        self.check_thread()?;
        let canonical = self.pin_canonical(object)?;
        match query_interface(&canonical, native_guid(iid)) {
            Ok(interface) => {
                let result = operation(interface.as_raw());
                drop(interface);
                Ok(Some(result))
            }
            Err(NativeComError::HResult { result, .. }) if result.0 == 0x8000_4002u32 as i32 => {
                Ok(None)
            }
            Err(error) => Err(error),
        }
    }

    /// Query a generated COM interface through windows-core and execute a
    /// typed call while its owned reference is alive. The caller supplies an
    /// interface type selected from the finite generated binding module; no
    /// arbitrary guest IID or vtable slot can enter this path.
    pub(super) fn with_typed_interface<I: Interface, R>(
        &self,
        object: ComObjectId,
        operation: impl FnOnce(&I) -> R,
    ) -> Result<Option<R>, NativeComError> {
        self.check_thread()?;
        let canonical = self.pin_canonical(object)?;
        match canonical.cast::<I>() {
            Ok(interface) => Ok(Some(operation(&interface))),
            Err(error) if error.code().0 == 0x8000_4002u32 as i32 => Ok(None),
            Err(error) => Err(NativeComError::HResult {
                operation: "QueryInterface",
                result: error.code(),
            }),
        }
    }

    /// Transfer one generated interface reference into the canonical object
    /// table without exposing its pointer to runtime code.
    pub(super) fn insert_typed_owned<I: Interface>(
        &self,
        interface: I,
    ) -> Result<ComObjectId, NativeComError> {
        self.insert_owned(interface.into_raw())
    }

    /// Retain an SDK STGMEDIUM after IDataObject::GetData. The medium is moved
    /// out only after owner validation and token allocation; callers still own
    /// it and must release it normally if this operation returns an error.
    pub(super) fn store_medium(
        &self,
        medium: &mut STGMEDIUM,
    ) -> Result<Win16ComHostOwnedMediumId, NativeComError> {
        self.check_thread()?;
        let id = Win16ComHostOwnedMediumId {
            owner: self.owner_identity,
            id: allocate_identity(&NEXT_NATIVE_COM_MEDIUM_ID)?,
        };
        let mut state = self.state.borrow_mut();
        let owned = std::mem::replace(medium, STGMEDIUM::default());
        state.media.insert(id, owned);
        Ok(id)
    }

    /// Consume one retained medium token and invoke the SDK cleanup routine on
    /// the owning STA, after removing it from the table so COM Release may
    /// reenter without a live RefCell borrow.
    pub(super) fn release_medium(
        &self,
        medium: Win16ComHostOwnedMediumId,
    ) -> Result<(), NativeComError> {
        self.check_thread()?;
        if !medium.is_valid() || medium.owner != self.owner_identity {
            return Err(NativeComError::InvalidOwnerIdentity);
        }
        let native = {
            let mut state = self.state.borrow_mut();
            state
                .media
                .remove(&medium)
                .ok_or(NativeComError::UnknownMedium(medium))?
        };
        // SAFETY: the table owns this complete SDK STGMEDIUM exactly once, and
        // ReleaseStgMedium is the documented cleanup for all union arms and
        // optional pUnkForRelease ownership.
        unsafe { ReleaseStgMedium(&native) };
        Ok(())
    }

    fn pin_canonical(&self, object: ComObjectId) -> Result<Arc<IUnknown>, NativeComError> {
        self.state
            .borrow()
            .by_id
            .get(&object)
            .map(|entry| Arc::clone(&entry.canonical))
            .ok_or(NativeComError::UnknownObject(object))
    }

    fn check_thread(&self) -> Result<(), NativeComError> {
        // SAFETY: GetCurrentThreadId has no pointer or initialization preconditions.
        let current = { crate::windows::win32_safe::current_thread_id() };
        if current != self.owner_thread {
            return Err(NativeComError::WrongThread {
                owner: self.owner_thread,
                current,
            });
        }
        let mut apartment: APTTYPE = 0;
        let mut qualifier = 0;
        // SAFETY: output slots are valid; this also verifies COM is still
        // initialized on the owner thread before any apartment-bound Release.
        let result = unsafe { CoGetApartmentType(&mut apartment, &mut qualifier) };
        if result < 0 {
            return Err(NativeComError::ApartmentQuery(HRESULT(result)));
        }
        if !matches!(apartment, APTTYPE_STA | APTTYPE_MAINSTA) {
            return Err(NativeComError::WrongApartment(apartment));
        }
        Ok(())
    }

    /// Owner-thread teardown releases every bridge-owned COM reference only
    /// after moving the entries out of the RefCell, so native Release can
    /// reenter without aliasing the table.
    pub(super) fn shutdown(&self) -> Result<(), NativeComError> {
        self.check_thread()?;
        // Replace the table before releasing interfaces. The short RefCell
        // borrow ends before COM Release can reenter this USER STA.
        let mut state = self.state.replace(Win16ComObjectState::empty());
        let media = std::mem::take(&mut state.media);
        state.by_unknown.clear();
        // RefCell state is already empty before invoking native Release, so a
        // reentrant callback cannot alias the object/media table borrow.
        for (_, medium) in media {
            // SAFETY: each table entry is one complete, owner-thread-owned
            // STGMEDIUM and shutdown is running on the initialized STA.
            unsafe { ReleaseStgMedium(&medium) };
        }
        drop(state);
        Ok(())
    }
}

fn allocate_identity(counter: &AtomicU64) -> Result<u64, NativeComError> {
    counter
        .try_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
            current.checked_add(1).filter(|next| *next != 0)
        })
        .map_err(|_| NativeComError::IdentitySpaceExhausted)
}

impl Drop for Win16ComObjects {
    fn drop(&mut self) {
        // SAFETY: GetCurrentThreadId has no pointer or initialization preconditions.
        let current = { crate::windows::win32_safe::current_thread_id() };
        if current == self.owner_thread {
            if self.shutdown().is_err() {
                // If COM was already uninitialized or the worker lost its STA,
                // leaking is safer than dropping apartment-bound interfaces
                // after COM teardown.
                let state = std::mem::replace(self.state.get_mut(), Win16ComObjectState::empty());
                std::mem::forget(state);
            }
        } else {
            // windows-core IUnknown drops Release natively. Preserve COM
            // apartment affinity by intentionally leaking wrappers on a
            // wrong-thread final drop instead of releasing them there.
            let state = std::mem::replace(self.state.get_mut(), Win16ComObjectState::empty());
            std::mem::forget(state);
        }
    }
}

fn native_guid(guid: Guid) -> NativeGuid {
    NativeGuid::from_values(guid.data1, guid.data2, guid.data3, guid.data4)
}

fn query_interface(
    unknown: &IUnknown,
    iid: NativeGuid,
) -> Result<NativeComInterfaceLease, NativeComError> {
    let mut output = ptr::null_mut();
    // SAFETY: output is writable and iid is an owned GUID. The IUnknown wrapper
    // supplies the official generated QueryInterface vtable entry.
    let result = unsafe { unknown.query(&iid, &mut output) };
    if result.0 < 0 {
        return Err(NativeComError::HResult {
            operation: "QueryInterface",
            result,
        });
    }
    if output.is_null() {
        return Err(NativeComError::InvalidQueryResult);
    }
    // SAFETY: successful QueryInterface transfers one owned COM interface ref.
    Ok(NativeComInterfaceLease(unsafe {
        IUnknown::from_raw(output)
    }))
}
